    retval = psspyc.vsc_dc_converter_data(name, ic, intgar, realar)
    ierr = retval
    if throwPsseExceptions == True and ierr > 0:
        raise Vsc_Dc_Converter_DataError('vsc_dc_converter_data', ierr)
