    if ncon == None:
        ncon = 0
    rdata = _makeValidListArg(rdata, _f, int(ncon))
    arrayinfomap = {}
    arrayinfomap.update(dict([('idata' + str(idx + 1), [idata, idx]) for idx in range(int(nicn))]))
    arrayinfomap.update(dict([('chdata' + str(idx + 1), [chdata, idx]) for idx in range(int(nicn))]))
    arrayinfomap.update(dict([('rdata' + str(idx + 1), [rdata, idx]) for idx in range(int(ncon))]))
    _updateArgs(arrayinfomap, kwds)
    retval = psspyc.add_mtdcline_model(dc, model, nicn, idata, chdata, ncon, rdata)
