    if numberlines == None:
        numberlines = _i
    if prtparams == None:
        prtparams = _i
    arrayinfomap = {}
    arrayinfomap.update(dict([('contingarray' + str(idx + 1), [contingarray, idx]) for idx in range(int(nconting))]))
